  3	import hotel.reservations.Reservation;
  4	import hotel.reservations.ReservationStore;
  5	import java.math.BigDecimal;
  6	import java.time.YearMonth;
  7	import java.util.ArrayList;
  8	import java.util.Comparator;
  9	import java.util.List;
 10	
 11	/**
 12	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
 13	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
 14	 */
 15	public final class RevenueReport {
 16	
 17	    private final ReservationStore store;
 18	
 19	    public RevenueReport(ReservationStore store) {
 20	        this.store = store;
 21	    }
 22	
 23	    public String generate(YearMonth month) {
 24	        List<Reservation> withRevenue = new ArrayList<>();
 25	        for (Reservation reservation : store.all()) {
 26	            boolean keptMoney = reservation.amountKept().signum() > 0;
 27	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
 28	            if (keptMoney && startsInMonth) {
 29	                withRevenue.add(reservation);
 30	            }
 31	        }
 32	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
 33	
 34	        StringBuilder csv = new StringBuilder();
 35	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 36	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
 37	        for (Reservation reservation : withRevenue) {
 38	            csv.append(reservation.id()).append(',')
 39	                    .append(reservation.roomNumber()).append(',')
 40	                    .append(reservation.checkIn()).append(',')
 41	                    .append(reservation.checkOut()).append(',')
 42	                    .append(reservation.status()).append(',')
 43	                    .append(reservation.amountKept().toPlainString()).append('\n');
 44	            revenue = revenue.add(reservation.amountKept());
 45	        }
 46	        csv.append("total,").append(revenue.toPlainString()).append('\n');
 47	        return csv.toString();
 48	    }
 49	}
 50	package hotel.web;
 51	
 52	import com.fasterxml.jackson.databind.ObjectMapper;
 53	import com.fasterxml.jackson.databind.SerializationFeature;
 54	import com.fasterxml.jackson.databind.json.JsonMapper;
 55	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 56	import hotel.messages.SentMessages;
 57	import hotel.reports.OccupancyReport;
 58	import hotel.reports.RevenueReport;
 59	import hotel.reservations.ErrorCode;
 60	import hotel.reservations.Guest;
 61	import hotel.reservations.HotelException;
 62	import hotel.reservations.NewReservation;
 63	import hotel.reservations.ReservationService;
 64	import hotel.rooms.Rooms;
 65	import io.javalin.Javalin;
 66	import io.javalin.http.Context;
 67	import io.javalin.json.JavalinJackson;
 68	import java.time.LocalDate;
 69	import java.time.YearMonth;
 70	import java.time.format.DateTimeParseException;
 71	
 72	/** The HTTP API the inn's website and front desk call. */
 73	public final class HttpApi {
 74	
 75	    private final Javalin server;
 76	    private final Rooms rooms;
 77	    private final ReservationService reservations;
 78	    private final SentMessages sentMessages;
 79	    private final OccupancyReport occupancyReport;
 80	    private final RevenueReport revenueReport;
 81	
 82	    public HttpApi(
 83	            Rooms rooms,
 84	            ReservationService reservations,
 85	            SentMessages sentMessages,
 86	            OccupancyReport occupancyReport,
 87	            RevenueReport revenueReport) {
 88	        this.rooms = rooms;
 89	        this.reservations = reservations;
 90	        this.sentMessages = sentMessages;
 91	        this.occupancyReport = occupancyReport;
 92	        this.revenueReport = revenueReport;
 93	
 94	        ObjectMapper jsonMapper = JsonMapper.builder()
 95	                .addModule(new JavaTimeModule())
 96	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 97	                .build();
 98	        this.server = Javalin.create(config -> {
 99	            config.showJavalinBanner = false;
100	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
101	        });
102	        registerRoutes();
103	        registerErrorHandling();
104	    }
105	
106	    public Javalin server() {
107	        return server;
108	    }
109	
110	    private void registerRoutes() {
111	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
112	
113	        server.post("/reservations", ctx -> {
114	            NewReservation request = readNewReservation(ctx);
115	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
116	        });
117	        server.get("/reservations/{id}", ctx ->
118	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
119	        server.post("/reservations/{id}/confirmation", ctx ->
120	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
121	        server.post("/reservations/{id}/cancellation", ctx ->
122	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
123	        server.post("/reservations/{id}/check-in", ctx ->
124	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
125	        server.post("/reservations/{id}/check-out", ctx ->
126	                ctx.json(reservations.checkOut(reservationId(ctx))));
127	        server.get("/reservations/{id}/document", ctx ->
128	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
129	
130	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
131	
132	        server.get("/reports/occupancy", ctx -> {
133	            LocalDate night = readDate(ctx);
134	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
135	        });
136	        server.get("/reports/revenue", ctx -> {
137	            YearMonth month = readMonth(ctx);
138	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
139	        });
140	    }
141	
142	    private void registerErrorHandling() {
143	        server.exception(HotelException.class, (exception, ctx) -> {
144	            ctx.status(httpStatus(exception.errorCode()));
145	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
146	        });
147	    }
148	
149	    private static int httpStatus(ErrorCode errorCode) {
150	        return switch (errorCode) {
151	            case INVALID_REQUEST -> 400;
152	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
153	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
154	            case CAPACITY_EXCEEDED -> 422;
155	        };
156	    }
157	
158	    private static NewReservation readNewReservation(Context ctx) {
159	        CreateReservationRequest body;
160	        try {
161	            body = ctx.bodyAsClass(CreateReservationRequest.class);
162	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
163	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
164	        }
165	        if (body == null
166	                || body.roomNumber() == null
167	                || isBlank(body.guestName())
168	                || isBlank(body.guestEmail())
169	                || isBlank(body.guestCpf())
170	                || body.checkIn() == null
171	                || body.checkOut() == null
172	                || body.guests() == null
173	                || body.ratePlan() == null) {
174	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
175	        }
176	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
177	        return new NewReservation(
178	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
179	    }
180	
181	    private static long reservationId(Context ctx) {
182	        String id = ctx.pathParam("id");
183	        try {
184	            return Long.parseLong(id);
185	        } catch (NumberFormatException notANumber) {
186	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
187	        }
188	    }
189	
190	    private static LocalDate readDate(Context ctx) {
191	        String date = requiredQueryParam(ctx, "date");
192	        try {
193	            return LocalDate.parse(date);
194	        } catch (DateTimeParseException badDate) {
195	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
196	        }
197	    }
198	
199	    private static YearMonth readMonth(Context ctx) {
200	        String month = requiredQueryParam(ctx, "month");
201	        try {
202	            return YearMonth.parse(month);
203	        } catch (DateTimeParseException badMonth) {
204	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
205	        }
206	    }
207	
208	    private static String requiredQueryParam(Context ctx, String name) {
209	        String value = ctx.queryParam(name);
210	        if (value == null) {
211	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
212	        }
213	        return value;
214	    }
215	
216	    private static boolean isBlank(String text) {
217	        return text == null || text.isBlank();
218	    }
219	}
220	package hotel.reservations;
221	
222	import hotel.documents.ReservationReceipt;
223	import hotel.messages.EmailSender;
224	import hotel.rooms.Room;
225	import hotel.rooms.Rooms;
226	import java.math.BigDecimal;
227	
228	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
229	public final class ReservationService {
230	
231	    static final String HOTEL_NAME = "Pousada Maré Alta";
232	
233	    private final Rooms rooms;
234	    private final ReservationStore store;
235	    private final PriceCalculator priceCalculator;
236	    private final EmailSender emailSender;
237	
238	    public ReservationService(
239	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
240	        this.rooms = rooms;
241	        this.store = store;
242	        this.priceCalculator = priceCalculator;
243	        this.emailSender = emailSender;
244	    }
245	
246	    public synchronized Reservation create(NewReservation request) {
247	        if (!request.checkOut().isAfter(request.checkIn())) {
248	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
249	        }
250	        if (request.guests() < 1) {
251	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
252	        }
253	        Room room = rooms.find(request.roomNumber())
254	                .orElseThrow(() -> new HotelException(
255	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
256	        if (request.guests() > room.capacity()) {
257	            throw new HotelException(
258	                    ErrorCode.CAPACITY_EXCEEDED,
259	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
260	        }
261	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
262	            throw new HotelException(
263	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
264	        }
265	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
266	        return store.add(request, price);
267	    }
268	
269	    public Reservation find(long reservationId) {
270	        return store.find(reservationId)
271	                .orElseThrow(() -> new HotelException(
272	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
273	    }
274	
275	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
276	    public synchronized Reservation confirm(long reservationId) {
277	        Reservation reservation = find(reservationId);
278	        if (reservation.status() != ReservationStatus.PENDING) {
279	            throw notAllowed(reservation, "confirm");
280	        }
281	        reservation.confirmPayment();
282	        store.update(reservation);
283	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
284	        emailSender.send(
285	                reservation.guest().email(),
286	                "Reserva confirmada - " + HOTEL_NAME,
287	                confirmationEmailBody(reservation, receipt));
288	        return reservation;
289	    }
290	
291	    /**
292	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
293	     * reservation was never paid, so nothing comes back).
294	     */
295	    public synchronized Reservation cancel(long reservationId) {
296	        Reservation reservation = find(reservationId);
297	        if (reservation.status() != ReservationStatus.PENDING
298	                && reservation.status() != ReservationStatus.CONFIRMED) {
299	            throw notAllowed(reservation, "cancel");
300	        }
301	        BigDecimal refund = switch (reservation.ratePlan()) {
302	            case STANDARD -> reservation.amountPaid();
303	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
304	        };
305	        reservation.cancel(refund);
306	        store.update(reservation);
307	        return reservation;
308	    }
309	
310	    public synchronized Reservation checkIn(long reservationId) {
311	        Reservation reservation = find(reservationId);
312	        if (reservation.status() != ReservationStatus.CONFIRMED) {
313	            throw notAllowed(reservation, "check in");
314	        }
315	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
316	        store.update(reservation);
317	        return reservation;
318	    }
319	
320	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
321	    public synchronized ReservationReceipt checkOut(long reservationId) {
322	        Reservation reservation = find(reservationId);
323	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
324	            throw notAllowed(reservation, "check out");
325	        }
326	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
327	        store.update(reservation);
328	        return new ReservationReceipt(reservation, roomOf(reservation));
329	    }
330	
331	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
332	    public ReservationReceipt receiptCopy(long reservationId) {
333	        Reservation reservation = find(reservationId);
334	        if (!reservation.isPaid()) {
335	            throw notAllowed(reservation, "issue a receipt for");
336	        }
337	        return new ReservationReceipt(reservation, roomOf(reservation));
338	    }
339	
340	    private Room roomOf(Reservation reservation) {
341	        return rooms.find(reservation.roomNumber()).orElseThrow();
342	    }
343	
344	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
345	        return "Olá, " + reservation.guest().name() + "!\n\n"
346	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
347	                + receipt.text() + "\n"
348	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
349	                + "Até breve!\n";
350	    }
351	
352	    private static HotelException notAllowed(Reservation reservation, String operation) {
353	        return new HotelException(
354	                ErrorCode.OPERATION_NOT_ALLOWED,
355	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
356	    }
357	}

